// Generated by AI (UnitTest MCP)
//! MindLeak MCP — an MCP (Model Context Protocol) server over stdio that exposes
//! the temporal context graph engine to coding agents.

mod maintenance;
mod server;
mod tools;

use std::path::{Path, PathBuf};

use mindleak_core::MindLeak;
use mindleak_session::SessionRegistry;
use mindleak_storage::{
    build_notice, head_sha, is_ancestor, resolve_database, resolve_workspace_path, DatabaseKind,
};

fn main() -> anyhow::Result<()> {
    mindleak_core::telemetry::init_tracing();
    let workspace = resolve_workspace();
    let stale_build = report_build_identity(&workspace);
    let database = resolve_database(
        &workspace,
        DatabaseKind::MindLeak,
        std::env::var("MINDLEAK_DB").ok().as_deref(),
    )?;
    let migrated_legacy = database.migrate_legacy_if_needed()?;
    database.ensure_parent()?;
    let storage_status = database.status("mindleak", migrated_legacy);
    let db_path = database.path.to_string_lossy().into_owned();
    let decay_policy = mindleak_core::config::load_decay_policy(&workspace)?;
    let working_set_size = mindleak_core::config::load_working_set_size();
    tracing::info!(
        prune_threshold = decay_policy.prune_threshold(),
        half_life_overrides = ?decay_policy.half_life_overrides(),
        working_set_size,
        "resolved decay policy"
    );
    let maintenance_config = maintenance::MaintenanceConfig::from_environment();
    // Display name for this process's sessions in reports. Since ADR-0054 it
    // is no part of the agent id, so two processes may disagree about it
    // without forking the identity of a session they both host.
    let display_name = std::env::var("MINDLEAK_AGENT").unwrap_or_else(|_| "agent".to_string());
    let sessions = SessionRegistry::new(&display_name).map_err(anyhow::Error::msg)?;
    let maintenance = maintenance::MaintenanceRuntime::start(
        maintenance_config,
        db_path.clone(),
        decay_policy.clone(),
        working_set_size,
    )?;
    let engine = MindLeak::open(&db_path)?
        .with_decay_policy(decay_policy)
        .with_working_set_size(working_set_size)
        .with_workspace_root(workspace.to_string_lossy().into_owned())
        .with_recall_floor(mindleak_core::config::load_recall_floor())
        .with_consolidation_min_interval(maintenance_config.min_interval.as_secs());
    // Collapse any absolute node ids this checkout wrote before paths were made
    // repo-relative (ADR-0038). Idempotent and prefix-scoped, so it costs a scan
    // on a healthy graph and keeps healing if a producer ever regresses.
    match engine.repair_workspace_paths() {
        Ok(outcome) if outcome.nodes_rewritten > 0 => tracing::info!(
            rewritten = outcome.nodes_rewritten,
            merged = outcome.nodes_merged,
            "collapsed absolute node ids onto their repo-relative identity"
        ),
        Ok(_) => {}
        // A repair failure must not stop the server: the graph is still usable
        // with split ids, and refusing to start would be the larger outage.
        Err(error) => tracing::warn!(%error, "workspace path repair skipped"),
    }
    tracing::info!(
        %db_path,
        repository_id = database.repository_id.as_deref().unwrap_or("none"),
        database_origin = ?database.origin,
        migrated_legacy,
        "mindleak-mcp ready"
    );
    // Non-blocking startup health probe for the optional semantic-recall backend
    // (ADR-0008): a detached thread reports whether recall is reachable, so an
    // operator sees `enabled`/`disabled` every run instead of a mystery 404 later.
    // It never delays startup or touches the deterministic hot path; on failure
    // the embedder's actionable error names the exact remediation (`ollama pull`).
    std::thread::spawn(|| {
        let embedder = mindleak_core::Embedder::default();
        match embedder.embed("startup recall health probe") {
            Ok(vector) => tracing::info!(
                model = %embedder.model,
                dims = vector.len(),
                "semantic recall: enabled"
            ),
            Err(error) => tracing::warn!(
                %error,
                "semantic recall: disabled (optional; the rest of MindLeak works without it)"
            ),
        }
    });
    let result = server::run(
        engine,
        sessions,
        maintenance.activity(),
        storage_status,
        stale_build,
    );
    maintenance.shutdown();
    result
}

/// Resolve the project root independently from the process launch directory.
/// Say plainly when the running binary is a stale build of the checkout it
/// serves. The servers have always reported `<version>+<sha>` at `initialize`;
/// nobody ever compared it, and a two-day-old local build was blamed on the
/// extension four times in one session before anyone looked.
/// Returns the notice when this binary is *behind* the checkout it serves, so
/// `open_session` can hand it to the agent. Logging alone was not enough for
/// the same reason `initialize` was not: an MCP client shows neither to the
/// agent, and a session ran a whole day against a stale build of this plane —
/// with the sha validation that refuses a fabricated commit id simply not
/// running, while every call still looked normal.
fn report_build_identity(workspace: &Path) -> Option<String> {
    let executable = std::env::current_exe().ok()?;
    let head = head_sha(workspace);
    // Whether the build has HEAD in its history. Answered here rather than
    // inside the rule so the decision stays pure and testable.
    let descends = head
        .as_deref()
        .and_then(|head| is_ancestor(workspace, head, env!("MINDLEAK_BUILD_SHA")));
    let notice = build_notice(
        &executable,
        workspace,
        env!("MINDLEAK_BUILD_SHA"),
        head.as_deref(),
        descends,
    )?;
    // Only a build behind the checkout it was built from is a warning.
    // Naming an installed build is information, and logging it louder than
    // that is how a real warning gets tuned out.
    if notice.stale {
        tracing::warn!("{}", notice.message);
        Some(notice.message)
    } else {
        tracing::info!("{}", notice.message);
        None
    }
}

fn resolve_workspace() -> PathBuf {
    let current = std::env::current_dir().unwrap_or_else(|_| ".".into());
    resolve_workspace_with(&current, |name| std::env::var(name).ok())
}

fn resolve_workspace_with<F>(current: &Path, environment: F) -> PathBuf
where
    F: Fn(&str) -> Option<String>,
{
    let configured = environment("MINDLEAK_WORKSPACE");
    resolve_workspace_path(current, configured.as_deref())
}

#[cfg(test)]
mod tests {
    use super::*;
    use mindleak_storage::{resolve_database_in, DatabaseOrigin};

    #[test]
    fn workspace_defaults_to_process_directory() {
        let current = Path::new("current");
        assert_eq!(resolve_workspace_with(current, |_| None), current);
        assert_eq!(
            resolve_workspace_with(current, |_| Some("  ".to_string())),
            current
        );
    }

    #[test]
    fn relative_workspace_resolves_from_process_directory() {
        let current = Path::new("current");
        assert_eq!(
            resolve_workspace_with(current, |name| {
                (name == "MINDLEAK_WORKSPACE").then(|| "projects/app".to_string())
            }),
            current.join("projects/app")
        );
    }

    #[test]
    fn absolute_workspace_is_preserved() {
        let absolute = std::env::temp_dir().join("mindleak-workspace");
        assert_eq!(
            resolve_workspace_with(Path::new("other"), |name| {
                (name == "MINDLEAK_WORKSPACE").then(|| absolute.to_string_lossy().into_owned())
            }),
            absolute
        );
    }

    #[test]
    fn default_database_follows_the_resolved_workspace_outside_git() {
        let workspace =
            std::env::temp_dir().join(format!("mindleak-mcp-scratch-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&workspace);
        std::fs::create_dir_all(&workspace).unwrap();
        let resolved = resolve_database_in(
            &workspace,
            DatabaseKind::MindLeak,
            None,
            &workspace.join("state"),
        )
        .unwrap();
        assert_eq!(resolved.path, workspace.join(".mindleak").join("graph.db"));
        assert_eq!(resolved.origin, DatabaseOrigin::Workspace);
        std::fs::remove_dir_all(workspace).unwrap();
    }
}
